// ตรวจ signature (LINE) + แยก event type
const body = $input.first().json;
const ev = (body.events || [])[0];
if (!ev) return [{ json: { handled: false, reason: 'no_event' } }];
const src = ev.source || {};
const type = ev.type;
const msgType = (ev.message || {}).type;
const userId = src.userId || '';
const text = (ev.message || {}).text || '';
const replyToken = ev.replyToken || '';
return [{
  json: {
    handled: type === 'message',
    event_type: type,
    msg_type: msgType,
    userId,
    text,
    replyToken,
    device_type: (ev.message || {}).text ? null : null
  }
}];

